package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class AssociativeArithmeticTest {
 @Test public void bothDirectionsRequireOriginalOrderAndNewGroupValueIndependentOfKeys(){Checker c=new Checker();for(String id:List.of(AssociativeArithmetic.ADD,AssociativeArithmetic.MUL))for(int direction=0;direction<2;direction++)for(int[] v:List.of(new int[]{2,3,4},new int[]{0,0,1000000},new int[]{1000000,0,0},new int[]{1000000,0,1000000},new int[]{100,100,100})){long ab=id.equals(AssociativeArithmetic.ADD)?(long)v[0]+v[1]:(long)v[0]*v[1],bc=id.equals(AssociativeArithmetic.ADD)?(long)v[1]+v[2]:(long)v[1]*v[2],total=id.equals(AssociativeArithmetic.ADD)?ab+v[2]:ab*v[2];if(ab>1000000||bc>1000000||total>1000000)continue;Question q=AssociativeArithmetic.make(id,v[0],v[1],v[2],direction);long inner=direction==0?bc:ab;List<String> answer=List.of(""+v[0],""+v[1],""+v[2],""+inner,""+total);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(c.check(q,List.of(),answer).correct());for(int i=0;i<5;i++){List<String> wrong=new ArrayList<>(answer);wrong.set(i,""+(Long.parseLong(wrong.get(i))+1));assertEquals(i,c.check(q,List.of(),wrong).index);}HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(7,h.size());long[] expected={v[0],v[1],v[2],direction==0?ab:bc,total,inner,total};for(int i=0;i<7;i++)assertTrue(h.step(i).accepts(""+expected[i]));assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
 @Test public void completeSmallDomainsIncludeZerosAndRepeatOnlyAfterAllConditions(){for(String id:List.of(AssociativeArithmetic.ADD,AssociativeArithmetic.MUL)){CurriculumLimits l=new CurriculumLimits("minGiven=0;maxGiven=3;maxResult=3;nonnegative=true");Set<String> all=new HashSet<>();for(int a=0;a<=3;a++)for(int b=0;b<=3;b++)for(int c=0;c<=3;c++){int ab=id.equals(AssociativeArithmetic.ADD)?a+b:a*b,bc=id.equals(AssociativeArithmetic.ADD)?b+c:b*c,total=id.equals(AssociativeArithmetic.ADD)?a+b+c:a*b*c;if(ab<=3&&bc<=3&&total<=3)for(int d=0;d<2;d++)all.add(AssociativeArithmetic.make(id,a,b,c,d).signature());}Generator g=new Generator(new Random(265));List<String> history=new ArrayList<>();for(int i=0;i<all.size();i++){Question q=g.next(id,history,false,l);assertTrue(all.contains(q.signature()));assertFalse(history.contains(q.signature()));history.add(q.signature());}assertEquals(history.get(0),g.next(id,history,false,l).signature());}}
 @Test public void normalGradeSixHasFreshBothGroupingDirectionsAndLargeOperands(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);Generator g=new Generator(new Random(265));for(String id:List.of(AssociativeArithmetic.ADD,AssociativeArithmetic.MUL)){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));List<String> history=new ArrayList<>();Set<Integer> directions=new HashSet<>();boolean large=false,positive=false;for(int i=0;i<150;i++){Question q=g.next(id,history,false,GlobalCurriculum.limits(pack,id,6));assertFalse(history.contains(q.signature()));history.add(q.signature());AssociativeArithmetic.Givens v=AssociativeArithmetic.read(q);directions.add(v.direction());large|=Math.max(v.a(),Math.max(v.b(),v.c()))>=100000;positive|=v.total()>0;}assertEquals(2,directions.size());assertTrue(large);assertTrue(positive);}}
}
